/**
 * Compute the Butterfly Curve at parameter t.
 * @param {number} t - The parameter, typically in [0, 12 * Math.PI].
 * @returns {{ x: number, y: number }} The (x, y) coordinates on the curve.
 */
function butterfly(t) {
  const term = Math.exp(Math.cos(t))
    - 2 * Math.cos(4 * t)
    - Math.pow(Math.sin(t / 12), 5);

  const x = sin(t) * term;
  const y = cos(t) * term;

  return { x, y };
}

/**
 * Perform a single integration step of the Lorenz attractor system.
 * @param {{ x: number, y: number, z: number }} state - Current state variables.
 * @param {number} dt - Time step for integration.
 * @param {number} [sigma=10] - Parameter sigma (Prandtl number).
 * @param {number} [rho=28] - Parameter rho (Rayleigh number).
 * @param {number} [beta=8/3] - Parameter beta.
 * @returns {{ x: number, y: number, z: number }} New state after one time step.
 */
function lorenzStep(state, dt, sigma = 10, rho = 28, beta = 8 / 3) {
  const { x, y, z } = state;
  const dx = sigma * (y - x);
  const dy = x * (rho - z) - y;
  const dz = x * y - beta * z;

  return {
    x: x + dx * dt,
    y: y + dy * dt,
    z: z + dz * dt,
  };
}

/**
 * Compute the iteration count for the Spider Fractal at a given complex point c.
 * @param {number} cRe - Real part of the complex parameter c.
 * @param {number} cIm - Imaginary part of the complex parameter c.
 * @param {number} [maxIter=100] - Maximum number of iterations.
 * @param {number} [bailOut=2] - Escape radius threshold.
 * @returns {number} Iteration count at which the sequence diverges (<= maxIter).
 */
function spiderIter(cRe, cIm, maxIter = 100, bailOut = 2) {
  let zRe = 0;
  let zIm = 0;
  let pRe = cRe;
  let pIm = cIm;
  const bail2 = bailOut * bailOut;

  for (let i = 0; i < maxIter; i++) {
    // z = z^2 + p
    const tmpRe = zRe * zRe - zIm * zIm + pRe;
    const tmpIm = 2 * zRe * zIm + pIm;

    // p = p/2 + z
    pRe = pRe / 2 + zRe;
    pIm = pIm / 2 + zIm;

    zRe = tmpRe;
    zIm = tmpIm;

    if (zRe * zRe + zIm * zIm > bail2) {
      return i;
    }
  }

  return maxIter;
}

