	implemented a simple butterfly curve with varying colors based on a random palette.
	Overlaps with a lorenz attractor, which adds pattern and some noise.

	Join the Birb's Nest Discord for friendly creative coding community
	and future challenges and contributions: https://discord.gg/S8c7qcjw2b
	WCCC-Contributions: https://openprocessing.org/curation/78544
*/

let seed, pal, FG, BG, CBG, S;
let lPt, iPt;

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("butterfly curve of colored dots with overlayed lorenz attractor for curvy pattern");
	frameRate(60);
	S = max(width, height) / TAU;

	seed = ~~random(987654321);
	noiseSeed(seed);
	randomSeed(seed);

	pal = shuffle([...random(palettes)]); // .map(e => e + "80");
	BG = random(pal);
	BG = adjColorBrightness(adjColorSaturation(BG, 1.5), 0.25);
	FG = adjColorBrightness(adjColorSaturation(BG, 0.75), 1.5);
	if (!CBG) CBG = BG;

	lPt = { // lorenz point
		x: random()-0.5, 
		y: random()-0.5, 
		z: random()-0.5, 
	}

	background(BG);
	drawBackground(BG);
	noStroke();
	strokeCap(ROUND);
	strokeWeight(3);
	fill("rgba(255,140,0,0.5)");
}

function draw() {
	translate(width/2, height/2);

	const t = millis() / 1000;

	const clr = getLerpedColor(pal, fract(t));
	clr.setAlpha(128);
	// fill(clr);
	stroke(clr);

	// 1
	const pt1 = butterfly(t);
	// circle(pt1.x * S, pt1.y * S, 4);

	// 2 lorenzStep
	lPt = lorenzStep(lPt, random(0.01, 0.02)); // 0.015
	// circle(lPt.x * S/10, lPt.y * S/10, 4);
	// circle(-lPt.x * S/10, lPt.y * S/10, 4);
	if (iPt) {
		const x1 = -iPt.x * S/10;
		const y1 = iPt.y * S/10;
		const x2 = -lPt.x * S/10;
		const y2 = lPt.y * S/10;
		line(x1, y1, x2, y2);
		// console.log(`line(${nf(x1,0,1)}, ${nf(y1,0,1)}, ${nf(x2,0,1)}, ${nf(y2,0,1)});`);
	}
	iPt = { x: lPt.x, y: lPt.y };
	// console.log(iPt, lPt);
}

function drawBackground(bg) {
	push()
	const ctx = drawingContext;
	const gradient = ctx.createRadialGradient(
		width/2, height/2, max(width, height)/1000, 
		width/2, height/2, max(width, height)*0.65
	);
	gradient.addColorStop(0.3, bg);
	gradient.addColorStop(1, color(0, 16));

	// Set the fill style and draw a rectangle
	ctx.fillStyle = gradient;
	ctx.fillRect(0, 0, width, height);

	stroke(0, 50)
	strokeWeight(1.25)
	for (let y = 3; y < height; y += 4) {
		line(0, y, width, y)
	}

	pop()
}

function mousePressed() {
	if (mouseButton !== RIGHT && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > width * 0.1) setup();
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
